export const techActivities={binary:['I explored binary.','coding-binary'],sequence:['I ran a robot program.','coding-sequence'],rule:['I tried an if / then rule.','coding-rule'],syntax:['I built a toy code command.','coding-syntax'],ai:['I tested learning from examples.','coding-ai'],sensors:['I tried a robot sensor.','robotics-sensors'],drone:['I tested rotors and air.','robotics-drone'],steward:['I planned care for our shared home.','robotics-care'],farm:['My robot helped with a garden.','robotics-jobs'],construction:['My robot helped build.','robotics-jobs'],tidy:['My robot helped tidy.','robotics-jobs'],fire:['I tried a pretend fire rescue.','robotics-jobs'],recycle:['My robot helped reuse materials.','robotics-jobs'],care:['My robot helped care for a shared space.','robotics-jobs']};
const bool=v=>v===true;
export function normalizeTech(raw={}){const r=raw&&typeof raw==='object'?raw:{};return {bits:Number.isInteger(r.bits)&&r.bits>=0&&r.bits<=15?r.bits:0,queue:(Array.isArray(r.queue)?r.queue:[]).filter(k=>['right','up','down'].includes(k)).slice(0,8),sequenceRan:bool(r.sequenceRan),dry:r.dry!==false,thenWater:r.thenWater!==false,ruleRan:bool(r.ruleRan),syntax:{word:bool(r.syntax?.word),open:bool(r.syntax?.open),close:bool(r.syntax?.close),ran:bool(r.syntax?.ran)},examples:[...new Set((Array.isArray(r.examples)?r.examples:[]).filter(k=>['plant','machine'].includes(k)))],probe:Number.isInteger(r.probe)&&r.probe>=0&&r.probe<3?r.probe:0,aiRan:bool(r.aiRan),blocked:r.blocked!==false,sensorRan:bool(r.sensorRan),air:r.air!==false,droneRan:bool(r.droneRan),robotId:typeof r.robotId==='string'&&/^m[1-9]\d{0,5}$/.test(r.robotId)?r.robotId:null,job:['farm','construction','tidy','fire','recycle','care'].includes(r.job)?r.job:'tidy',jobRan:bool(r.jobRan),tidyPlace:['shelf','box'].includes(r.tidyPlace)?r.tidyPlace:null,jobPlanned:bool(r.jobPlanned),steward:{reduce:bool(r.steward?.reduce),ask:bool(r.steward?.ask),help:bool(r.steward?.help)},completed:[...new Set((Array.isArray(r.completed)?r.completed:[]).filter(k=>Object.hasOwn(techActivities,k)))]};}
export function techRoute(queue){const trace=[[0,1]];let blocked=false;for(const cmd of queue){const [x,y]=trace.at(-1),[dx,dy]=cmd==='right'?[1,0]:cmd==='up'?[0,-1]:[0,1],nx=x+dx,ny=y+dy;if(nx<0||nx>4||ny<0||ny>2||(nx===2&&ny===1)){blocked=true;break;}trace.push([nx,ny]);}const p=trace.at(-1);return {trace,blocked,delivered:p[0]===4&&p[1]===1};}
export const techExamples={plant:{features:[0,3],label:'plant'},machine:{features:[4,0],label:'machine'}};
export const techProbes=[{name:'New plant',features:[0,2],truth:'plant'},{name:'New rover',features:[3,0],truth:'machine'},{name:'Leaf-shaped robot',features:[0,3],truth:'machine'}];
export function techPredict(examples,probe){if(!examples.length)return 'need-examples';const distances=examples.map(k=>techExamples[k]).filter(Boolean).map(e=>({label:e.label,d:e.features.reduce((sum,n,i)=>sum+(n-probe.features[i])**2,0)})).sort((a,b)=>a.d-b.d);if(!distances.length||distances[0].d>4||distances[0].d===distances[1]?.d)return 'unsure';return distances[0].label;}
export const techJobs={farm:{name:'Water a garden',icon:'💧',tools:['sprayer'],text:'A spray helper can water a waiting farm bed. People still check what plants need.'},construction:{name:'Help build',icon:'🏗️',tools:['gripper'],text:'The helper follows our prefab plan. People choose the place and check the result.'},tidy:{name:'Tidy toys',icon:'🧸',tools:['gripper','brush'],text:'Choose where the toys belong. The robot helps with our plan.'},fire:{name:'Pretend fire rescue',icon:'🚒',tools:['sprayer'],text:'A made-up training scene. Our spray robot clears pretend flames. Real fires need adult help and trained emergency teams.'},recycle:{name:'Reuse materials',icon:'♻️',tools:['gripper'],text:'Plan which clean model pieces can be reused. Robots help carry them; people decide what is suitable.'},care:{name:'Care for shared spaces',icon:'🌿',tools:['brush'],text:'First protect the plants and choose a safe route. Then our brush helper can tidy the shared path.'}};
export function techAvailableJobs(robot){return robot?.type==='helperbot'?Object.entries(techJobs).filter(([,j])=>j.tools.includes(robot.parts.module)).map(([id])=>id):[];}
export function techAction(raw,a,ctx={}){const s=normalizeTech(raw);let route=a.route||'home',message='',blueprint=null,pip=false,effect=null,home=false;const done=id=>{if(!s.completed.includes(id))s.completed.push(id)};
 if(a.type==='page')route=a.route;
 else if(a.type==='bit'&&[1,2,4,8].includes(a.value)){s.bits^=a.value;done('binary');route='binary';}
 else if(a.type==='command'&&['right','up','down'].includes(a.value)){if(s.queue.length<8)s.queue.push(a.value);s.sequenceRan=false;route='sequence';}
 else if(a.type==='sequence'){if(a.value==='undo')s.queue.pop();if(a.value==='clear')s.queue=[];if(a.value==='example')s.queue=['right','up','right','right','down','right'];s.sequenceRan=a.value==='run';if(s.sequenceRan)done('sequence');route=a.value==='run'?'sequence':'sequence-tools';}
 else if(a.type==='rule'){if(a.value==='sensor')s.dry=!s.dry;if(a.value==='then')s.thenWater=!s.thenWater;s.ruleRan=a.value==='run';if(s.ruleRan)done('rule');route='rule';}
 else if(a.type==='syntax'){if(['word','open','close'].includes(a.value))s.syntax[a.value]=!s.syntax[a.value];if(a.value==='example')s.syntax={word:true,open:true,close:true,ran:false};s.syntax.ran=a.value==='run';if(s.syntax.ran&&s.syntax.word&&s.syntax.open&&s.syntax.close)done('syntax');route=a.value==='example'?'syntax':'syntax';}
 else if(a.type==='teach'&&Object.hasOwn(techExamples,a.value)){if(!s.examples.includes(a.value))s.examples.push(a.value);s.aiRan=false;route='ai';}
 else if(a.type==='ai'){if(a.value==='probe')s.probe=(s.probe+1)%3;if(a.value==='reset')s.examples=[];s.aiRan=a.value==='test';if(s.aiRan&&s.examples.length)done('ai');route='ai';}
 else if(a.type==='sensor'){if(a.value==='path')s.blocked=!s.blocked;s.sensorRan=a.value==='run';if(s.sensorRan)done('sensors');route='sensors';}
 else if(a.type==='drone'){if(a.value==='air')s.air=!s.air;s.droneRan=a.value==='run';if(s.droneRan)done('drone');route='drone';}
 else if(a.type==='build'&&['helperbot','drone'].includes(a.value))blueprint=a.value;
 else if(a.type==='pip')pip=true;
 else if(a.type==='home')home=true;
 else if(a.type==='robot'&&ctx.robots?.some(m=>m.id===a.value&&m.type==='helperbot')){s.robotId=a.value;s.jobRan=false;route='robot-jobs';}
 else if(a.type==='job'){const robot=ctx.robots?.find(m=>m.id===s.robotId);if(techAvailableJobs(robot).includes(a.value)){s.job=a.value;s.jobRan=false;s.jobPlanned=false;route='job';}}
 else if(a.type==='job-plan'){if(['box','shelf'].includes(a.value))s.tidyPlace=a.value;else s.jobPlanned=true;s.jobRan=false;route='job';}
 else if(a.type==='job-run'){const robot=ctx.robots?.find(m=>m.id===s.robotId);route='job';if(techAvailableJobs(robot).includes(s.job)){if(s.job==='tidy'&&!s.tidyPlace||['care','recycle'].includes(s.job)&&!s.jobPlanned)message='Let’s make the plan together first.';else{s.jobRan=true;done(s.job);effect=s.job;message='Our helper followed the plan. People check and care for the result.';}}}
 else if(a.type==='steward'&&['reduce','ask','help'].includes(a.value)){s.steward[a.value]=true;if(Object.values(s.steward).every(Boolean))done('steward');route='steward';}
 return {tech:s,route,message,blueprint,pip,effect,home};}
