// Original schematic placeholders. State changes appear as static, repeatable pictures.
export function techArtKey(raw,art){const s=normalizeTech(raw);if(art==='binary')return 'binary-'+s.bits;if(art==='sequence'){const p=s.sequenceRan?techRoute(s.queue).trace.at(-1):[0,1];return 'sequence-'+(p[0]+p[1]*5);}if(art==='rule')return 'rule-'+(+s.dry+2*+s.thenWater+4*+s.ruleRan);if(art==='syntax')return 'syntax-'+(s.syntax.ran&&s.syntax.word&&s.syntax.open&&s.syntax.close?8:+s.syntax.word+2*+s.syntax.open+4*+s.syntax.close);if(art==='ai')return 'ai-'+(s.probe+3*(+s.examples.includes('plant')+2*+s.examples.includes('machine'))+12*+s.aiRan);if(art==='sensors')return 'sensors-'+(+s.blocked+2*+s.sensorRan);if(art==='drone')return 'drone-'+(+s.air+2*+s.droneRan);if(art==='job')return 'job-'+s.job+'-'+(+s.jobRan);if(art==='steward')return 'steward-'+(+s.steward.reduce+2*+s.steward.ask+4*+s.steward.help);return ['home','malik','mike','robot'].includes(art)?art:'robot';}
export const techArtKeys=['home','malik','mike','robot','syntax-8',...Array.from({length:16},(_,i)=>'binary-'+i),...Array.from({length:15},(_,i)=>'sequence-'+i),...['rule','syntax','steward'].flatMap(k=>Array.from({length:8},(_,i)=>k+'-'+i)),...Array.from({length:24},(_,i)=>'ai-'+i),...['sensors','drone'].flatMap(k=>Array.from({length:4},(_,i)=>k+'-'+i)),...Object.keys(techJobs).flatMap(k=>[0,1].map(i=>'job-'+k+'-'+i))];
export function techArt(key){const [kind,arg,flag]=key.split('-'),n=Number(arg)||0;let a='';const line=(x,y,t,size=18)=>`<text x="${x}" y="${y}" fill="#17384a" font-family="sans-serif" font-size="${size}" text-anchor="middle">${t}</text>`,bot=(x,y)=>`<g transform="translate(${x} ${y})"><rect x="-23" y="-25" width="46" height="42" rx="10" fill="#8aaabd" stroke="#17384a" stroke-width="3"/><rect x="-17" y="-17" width="34" height="13" rx="4" fill="#17384a"/><circle cx="-9" cy="-10" r="3" fill="#35bcb8"/><circle cx="9" cy="-10" r="3" fill="#35bcb8"/><circle cx="-16" cy="23" r="8" fill="#17384a"/><circle cx="16" cy="23" r="8" fill="#17384a"/></g>`,plant=(x,y)=>`<g transform="translate(${x} ${y})"><path d="M-17 5h34l-5 23h-24z" fill="#b88255"/><path d="M0 5v-37m0 20q-35 0-18-20Q0-32 0-12m0-9q30 0 20-22Q0-39 0-21" fill="#609e72" stroke="#315d48" stroke-width="3"/></g>`;
 if(kind==='binary'){for(let i=0;i<4;i++){const x=50+i*72,on=!!(n&(8>>i));a+=`<rect x="${x-26}" y="25" width="52" height="68" rx="10" fill="${on?'#f1ca65':'#17384a'}" stroke="#17384a" stroke-width="3"/>`+`<text x="${x}" y="67" fill="${on?'#17384a':'#fff8df'}" text-anchor="middle" font-family="sans-serif" font-size="30">${on?1:0}</text>`+line(x,116,8>>i);}a+=line(160,158,'= '+n,26);}
 else if(kind==='sequence'){for(let i=0;i<15;i++){const x=35+(i%5)*60,y=25+Math.floor(i/5)*48;a+=`<rect x="${x-24}" y="${y-18}" width="48" height="38" rx="5" fill="${i===7?'#9a7763':i===9?'#efcf74':'#f9f6e7'}" stroke="#879f99" stroke-width="2"/>`;if(i===7)a+=line(x,y+7,'▣');}a+=bot(35+(n%5)*60,25+Math.floor(n/5)*48)+line(160,176,'Start → around the rock → delivery',14);}
 else if(kind==='rule'){const dry=!!(n&1),water=!!(n&2),run=!!(n&4);a+=plant(220,120)+line(90,40,dry?'DRY':'WET')+line(90,82,'IF → THEN',22)+line(90,122,water?'WATER':'WAIT');if(run&&dry&&water)a+='<path d="M170 40l35 35m-27-8 27 25m-35-5 27 25" stroke="#3489ad" stroke-width="5"/>';a+=line(160,163,run?(dry&&water?'Pump on':'Pump waits'):'Tap Run to try',17);}
 else if(kind==='syntax'){if(n===8)a+=bot(270,110);const code=n===8?7:n;a+=line(160,78,`${code&1?'GO':'__'} ${code&2?'(':'_'} ${code&4?')':'_'}`,40)+line(160,140,n===8?'GO() → robot moves':n===7?'Matching pieces → GO()':'Tap the three code pieces',18);}
 else if(kind==='ai'){const probe=n%3,mask=Math.floor(n/3)%4,run=n>=12,examples=['plant','machine'].filter((_,i)=>mask&(1<<i)),answer=techPredict(examples,techProbes[probe]);a+=plant(55,63)+bot(260,55)+line(55,108,mask&1?'Example ✓':'Example ?',14)+line(260,108,mask&2?'Example ✓':'Example ?',14);a+=probe===0?plant(160,116):bot(160,110);if(probe===2)a+='<path d="M155 88q-25-30-30-5 5 20 30 5" fill="#609e72"/>';a+=line(160,169,run?'Computer says: '+answer:techProbes[probe].name,16);}
 else if(kind==='sensors'){a+=bot(n&2?(n&1?100:240):60,95)+`<path d="M30 135h260" stroke="#597b86" stroke-width="5"/>`;if(n&1)a+='<rect x="160" y="70" width="42" height="62" rx="6" fill="#b58f6b"/><path d="M115 80q50 15 0 30m10-42q70 25 0 54" fill="none" stroke="#35bcb8" stroke-width="4"/>';a+=line(160,168,n&2?(n&1?'Sensor → STOP':'Clear path → GO'):'Sense → computer → motor',16);}
 else if(kind==='drone'){const air=!!(n&1),fly=air&&!!(n&2),y=fly?45:100;a+=`<rect x="15" y="18" width="290" height="125" rx="12" fill="${air?'#b6dce6':'#b7bacd'}"/><path d="M25 135h270" stroke="#597b86" stroke-width="4"/><path d="M80 ${y}h160m-90 0v35m20-35v35" stroke="#c4ced8" stroke-width="8"/><ellipse cx="95" cy="${y}" rx="38" ry="8" fill="#17384a"/><ellipse cx="225" cy="${y}" rx="38" ry="8" fill="#17384a"/><rect x="133" y="${y+10}" width="54" height="30" rx="6" fill="#497ea8"/>`+line(160,167,air?(fly?'Air pushes down → drone up':'Earth: air around us'):'Moon vacuum: rotors cannot lift',16);}
 else if(kind==='job'){const done=flag==='1';a+=bot(done?200:75,105);if(arg==='farm'||arg==='care')a+=plant(260,116);else if(arg==='fire')a+=done?line(260,100,'✓',40):'<path d="M230 125q-20-40 20-80-10 30 20 40 25 40-10 40z" fill="#df9853"/>';else a+='<rect x="240" y="60" width="50" height="70" fill="#b58f6b"/><path d="M240 95h50" stroke="#17384a" stroke-width="3"/>';if(done)a+='<path d="M210 75l35 20m-30 0 25 15" stroke="#35bcb8" stroke-width="5"/>';a+=line(160,165,done?'We check the result together':'Plan → robot helps → check',17);}
 else if(kind==='steward'){a+=`<circle cx="160" cy="78" r="57" fill="#8fbecb"/><path d="M125 35l37 8 17 30-28 16-18 28-20-37zM181 85l25 5 10 25-22 12z" fill="#609e72"/>`+line(160,162,['Reduce waste','Ask first','Help together'].filter((_,i)=>n&(1<<i)).join(' · ')||'People + robots + nature',15);}
 else if(kind==='mike'){a+='<rect x="100" y="80" width="120" height="65" rx="12" fill="#faf7e8" stroke="#17384a" stroke-width="4"/><circle cx="160" cy="53" r="31" fill="#bf906c"/><path d="M127 45q5-43 66-9" fill="#c4ced8"/><path d="M135 52h20m10 0h20m-30 0h10" stroke="#17384a" stroke-width="4"/>'+line(160,172,'Professor Mike · coding guide',17);}
 else {a+=bot(160,90)+plant(260,113)+`<rect x="25" y="35" width="75" height="65" rx="6" fill="#17384a"/>`+`<text x="62" y="76" fill="#35bcb8" text-anchor="middle" font-size="24">01</text>`+line(160,166,kind==='malik'?'Malik · explore computing':'Build, code, test, help',18);}
 return `<svg xmlns="http://www.w3.org/2000/svg" width="320" height="180" viewBox="0 0 320 180"><rect width="320" height="180" rx="14" fill="#edf2e5"/>${a}</svg>`;}
export function techBackdrop(zone){const coding=zone==='coding';let a=`<rect width="1000" height="600" fill="${coding?'#b7d5dd':'#c5d8be'}"/><path d="M0 115h1000M0 565h1000" stroke="#93afa9" stroke-width="8"/><rect x="30" y="35" width="940" height="70" rx="15" fill="#17384a"/><text x="500" y="80" text-anchor="middle" fill="#fff7df" font-family="sans-serif" font-size="30">${coding?'MALIK + PROFESSOR MIKE · COMPUTER LAB':'KAITO + PIP · ROBOTICS BAY'}</text><path d="M140 490V250H850v240" fill="none" stroke="#e9ead5" stroke-width="38"/>`;
 for(const x of [250,500,750])a+=`<rect x="${x-85}" y="282" width="170" height="75" rx="12" fill="#899c9e" stroke="#17384a" stroke-width="4"/><rect x="${x-45}" y="264" width="90" height="50" rx="6" fill="#17384a"/><path d="M${x-30} 287h20m10 0h30" stroke="#35bcb8" stroke-width="6"/>`;
 a+=`<rect x="180" y="140" width="140" height="65" rx="16" fill="#ecf0df"/><rect x="680" y="140" width="140" height="65" rx="16" fill="#ecf0df"/><text x="250" y="170" text-anchor="middle" font-family="sans-serif" fill="#17384a" font-size="20">${coding?'Malik':'PIP'}</text><text x="750" y="170" text-anchor="middle" font-family="sans-serif" fill="#17384a" font-size="20">${coding?'Professor Mike':'Kaito'}</text><text x="140" y="550" text-anchor="middle" font-family="sans-serif" font-size="18" fill="#17384a">← HQ</text><text x="850" y="550" text-anchor="middle" font-family="sans-serif" font-size="18" fill="#17384a">Next door →</text>`;return `<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="600" viewBox="0 0 1000 600">${a}</svg>`;}
